 }

 static inline unsigned find_next_offset(struct rvt_qpn_table *qpt,
 					struct rvt_qpn_map *map, unsigned off,
-					unsigned n)
+					unsigned n, u16 qpt_mask)
 {
 	if (qpt_mask) {
 		off++;
 		if (((off & qpt_mask) >> 1) >= n)
 			off = (off | qpt_mask) + 2;
 	} else {
 		off = find_next_zero_bit(map->page, RVT_BITS_PER_PAGE, off);
 	}
 	return off;
 }

